text:
8.1 Skip connections through time
Time-axis version of ResNet/DenseNet. Directly connects distant time points.
h^{(t)} = f(h^{(t-1)}, x^{(t)}) + h^{(t-d)}

8.2 Leaky units
\mu^{(t)} \leftarrow \alpha\, \mu^{(t-1)} + (1-\alpha)\, v^{(t)}
Exponential Moving Average (EMA) form. If \alpha is close to 1, it is long-term information that changes slowly; if it is close to 0, it tracks rapid changes. It has the same structure as EMA-based channel estimation in wireless communication.

16.3 Masked Attention
Sometimes you want to restrict which tokens pay attention to which tokens. Implement this by masking the attention matrix:
\[
A_{ij} =
\begin{cases}
\mathrm{softmax}\ \text{값} & \text{허용}\\
0\ (\text{스코어}=-\infty) & \text{금지}
\end{cases}
\]
is primarily used in decoders and blocks the upper triangle (causal mask) to pay attention only to past tokens rather than future tokens. It is also utilized for optional data encoding in multimodal inputs.

Codes
#include &lt;stdio.h&gt;

using ull = unsigned long long int;
int a, b, c, K;

int _MIN(int a, int b)
{
    return (a &lt; b) ? a : b;
}

ull get_invalid_case(ull c, ull a, ull b)
{
    ull cnt = 0;

    for(int KK = 0; KK &lt;= K; ++KK)
    {
        int C = c - (a + b);
        int _min_val = _MIN(C + KK, K - KK);

        if(_min_val &gt;= 0)
        {
            cnt += (1ULL * (_min_val + 1) * (_min_val + 2)) / 2;
        }
    }

    return cnt;
}

int main(void)
{
    int t;
    scanf("%d", &t);
    while(t--)
    {
        scanf("%d%d%d%d", &a, &b, &c, &K);

        ull all_cases = 1ULL * (K + 1) * (K + 2) * (K + 3);
        all_cases /= 6;

        printf("%llu\n",
            all_cases -
            get_invalid_case(a, b, c) -
            get_invalid_case(b, c, a) -
            get_invalid_case(c, a, b));
    }
}

Codes
#include &lt;stdio.h&gt;

#define MAXN 100005
#define MAXM 200005
#define MAXL 100005
#define MAXS 300010

int eu_[MAXM], ev_[MAXM], ew_[MAXM];
int par_[MAXN], sz_[MAXN], nxt_[MAXN];
int deg_[MAXN], head_[MAXN + 1], pos_[MAXN], adj_[MAXM];
int sa_[MAXS], sb_[MAXS], snext_[MAXS];
int bucket_head_[MAXL + 2];
long long ans_[MAXL + 2];

int n_, q_, m_, lmax_;
int sc_, max_sched_;

int find_(int x) {
    while (par_[x] != x) { par_[x] = par_[par_[x]]; x = par_[x]; }
    return x;
}

void schedule_(int a, int b, int l) {
    if (l &gt; lmax_) return;
    sa_[sc_] = a; sb_[sc_] = b; snext_[sc_] = bucket_head_[l]; bucket_head_[l] = sc_; sc_++;
    if (l &gt; max_sched_) max_sched_ = l;
}

void run_threshold_(int w) {
    int i, x, l;
    for (i = 0; i &lt; n_; i++) deg_[i] = 0;
    for (i = 0; i &lt; m_; i++) if (ew_[i] &lt;= w) deg_[eu_[i]]++;
    head_[0] = 0;
    for (i = 0; i &lt; n_; i++) head_[i + 1] = head_[i] + deg_[i];
    for (i = 0; i &lt; n_; i++) pos_[i] = head_[i];
    for (i = 0; i &lt; m_; i++) if (ew_[i] &lt;= w) { adj_[pos_[eu_[i]]] = ev_[i]; pos_[eu_[i]]++; }

    for (i = 0; i &lt; n_; i++) { par_[i] = i; sz_[i] = 1; }
    sc_ = 0; max_sched_ = 0;

    for (x = 0; x &lt; n_; x++) {
        if (head_[x] == head_[x + 1]) { nxt_[x] = -1; continue; }
        nxt_[x] = adj_[head_[x]];
        for (i = head_[x] + 1; i &lt; head_[x + 1]; i++) schedule_(adj_[head_[x]], adj_[i], 2);
    }

    int empty_classes = 0;
    for (x = 0; x &lt; n_; x++) if (nxt_[x] == -1) empty_classes++;

    long long total_merges = 0, iso_s = 0, iso_prev = empty_classes, size_p;
    int e;

    for (l = 2; l &lt;= lmax_; l++) {
        iso_s += iso_prev;
        for (e = bucket_head_[l]; e != -1; e = snext_[e]) {
            int ra = find_(sa_[e]), rb = find_(sb_[e]);
            if (ra == rb) continue;
            int na = nxt_[ra], nb = nxt_[rb];
            int ea = (na == -1), eb = (nb == -1);
            if (sz_[ra] &lt; sz_[rb]) { int t = ra; ra = rb; rb = t; }
            par_[rb] = ra; sz_[ra] += sz_[rb];
            nxt_[ra] = (na != -1) ? na : nb;
            if (na != -1 && nb != -1) schedule_(na, nb, l + 1);
            if (ea || eb) empty_classes--;
            total_merges++;
        }
        bucket_head_[l] = -1;
        size_p = (long long)n_ - total_merges;
        ans_[l] += size_p + iso_s;
        iso_prev = empty_classes;
        if (l &gt;= max_sched_) {
            int ll;
            for (ll = l + 1; ll &lt;= lmax_; ll++) { iso_s += iso_prev; ans_[ll] += size_p + iso_s; }
            break;
        }
    }
}

int main() {
    int tc, i, w, l;
    for (i = 0; i &lt; MAXL + 2; i++) bucket_head_[i] = -1;
    scanf("%d", &tc);
    while (tc--) {
        scanf("%d %d %d", &n_, &q_, &m_);
        lmax_ = q_ + 1;
        for (i = 0; i &lt; m_; i++) {
            scanf("%d %d %d", &eu_[i], &ev_[i], &ew_[i]);
            eu_[i]--; ev_[i]--;
        }
        for (l = 0; l &lt;= lmax_ + 1; l++) ans_[l] = 0;
        for (w = 0; w &lt; 30; w++) run_threshold_(w);
        for (l = 2; l &lt;= lmax_; l++) {
            printf("%lld", ans_[l] - 30);
            if (l &lt; lmax_) printf(" ");
        }
        printf("\n");
    }
    return 0;
}

2. 자료구조 설계
그룹마다 독립적인 해시 테이블을 둔다.
struct Event {
    char name[MAX_NAME_LEN];
    int  h_key;            // 슬롯 상태 겸 인덱스
    int  n_participants;
    int  participant[5];
} event[MAX_GRP][MAX_HKEY];

해시 함수: djb2. 매 스텝 % MAX_HKEY로 누적해 [0, MAX_HKEY) 범위의 슬롯 인덱스를 얻는다.
충돌 처리: open addressing + 선형 탐사(linear probing).
유저 측 자료구조: 각 유저는 자신이 속한 일정 목록을 {gid, slot index, is_master}로 들고 있다.

여기서 중요한 설계 관찰이 하나 있다. 유저는 일정을 가리킬 때 슬롯 인덱스를 직접 저장하므로, “유저 → 일정” 조회(find_evt_idx)는 해시 탐사를 전혀 거치지 않는다. 해시 테이블의 탐사가 실제로 쓰이는 곳은 오직 addEvent 내부의 find / add뿐이다. 즉 버그가 숨을 수 있는 표면은 find/add 단 두 함수로 좁혀진다.






Note



디버깅에 들어가기 전에 “해시가 실제로 관여하는 코드 경로”를 먼저 좁혀두면, 원인 후보를 크게 줄일 수 있다. 자료구조가 인덱스를 직접 들고 있는 부분과 해시로 탐색하는 부분을 분리해서 보는 습관이 도움이 된다.

Codes
#define MAX_GRP         (100)
#define MAX_USER        (1000)
#define MAX_NAME_LEN    (16)
#define MAX_HKEY        (1007)

void mstrcpy(char dst[], const char src[]) {
    int c = 0;
    while ((dst[c] = src[c]) != 0) ++c;
}

int mstrcmp(const char str1[], const char str2[]) {
    int c = 0;
    while (str1[c] != 0 && str1[c] == str2[c]) ++c;
    return str1[c] - str2[c];
}

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while (c = *str++) {
        hash = (((hash &lt;&lt; 5) + hash) + c) % MAX_HKEY;
    }
    return hash % MAX_HKEY;
}

struct Event {
    char name[MAX_NAME_LEN];
    int  h_key;
    int  n_participants;
    int  participant[5];

    void delete_pid(int pid) {
        int i = 0;
        for (; i &lt; n_participants; ++i) {
            if (participant[i] == pid) break;
        }
        participant[i] = participant[n_participants - 1];
        --n_participants;
    }

    // key_designated == -1 : EMPTY (전체 초기화)
    // key_designated == -2 : DELETED (tombstone)
    void init(int key_designated = -1) {
        name[0] = 0;
        h_key   = key_designated;
        n_participants = 0;
    }

    void add_participant(int pid) {
        participant[n_participants++] = pid;
    }
} event[MAX_GRP][MAX_HKEY];

// EMPTY(h_key == -1)에서만 멈추고, DELETED(-2)는 통과한다.
Event* find(int gid, const char *key) {
    unsigned long h = hash(key);
    int cnt = MAX_HKEY;
    while (event[gid][h].h_key != -1 && cnt--) {
        if (mstrcmp(event[gid][h].name, key) == 0) {
            return &event[gid][h];
        }
        h = (h + 1) % MAX_HKEY;
    }
    return nullptr;
}

// DELETED 슬롯(name[0] == 0)을 재활용한다.
// 반드시 find가 nullptr을 반환한 직후에만 호출되어야 한다.
Event* add(int gid, const char *key) {
    unsigned long h = hash(key);
    while (event[gid][h].name[0] != 0) {
        if (mstrcmp(event[gid][h].name, key) == 0) {
            return nullptr;
        }
        h = (h + 1) % MAX_HKEY;
    }
    mstrcpy(event[gid][h].name, key);
    event[gid][h].h_key = h;
    return &event[gid][h];
}

struct User {
    int n_events;
    struct {
        int  key;
        int  gid;
        bool is_master;
    } event_info[100];

    void init() {
        n_events = 0;
    }

    void add_event(int gid, int event_key, bool master_flag) {
        event_info[n_events].key       = event_key;
        event_info[n_events].gid       = gid;
        event_info[n_events].is_master = master_flag;
        ++n_events;
    }

    void delete_event(int evt_id) {
        event_info[evt_id] = event_info[n_events - 1];
        --n_events;
    }

    int find_evt_idx(char ename[]) {
        for (int i = 0; i &lt; n_events; ++i) {
            auto evt = &event[event_info[i].gid][event_info[i].key];
            if (mstrcmp(evt-&gt;name, ename) != 0) continue;
            return i;
        }
        return -1;
    }
} user[MAX_USER];

void init() {
    for (int i = 0; i &lt; MAX_USER; ++i) {
        user[i].init();
    }
    for (int i = 0; i &lt; MAX_GRP; ++i) {
        for (int j = 0; j &lt; MAX_HKEY; ++j) {
            event[i][j].init();
        }
    }
}

void addEvent(int uid, char ename[], int groupid) {
    bool is_master = false;
    auto evt = find(groupid, ename);
    if (evt == nullptr) {
        evt = add(groupid, ename);
        is_master = true;
    }
    evt-&gt;add_participant(uid);
    user[uid].add_event(groupid, evt-&gt;h_key, is_master);
}

int deleteEvent(int uid, char ename[]) {
    int evt_id = user[uid].find_evt_idx(ename);
    if (evt_id == -1) {
        return 0;
    }

    int cnt = 1;
    auto  target = user[uid].event_info[evt_id];
    auto& evt    = event[target.gid][target.key];

    user[uid].delete_event(evt_id);

    if (target.is_master == true) {
        for (int i = 1; i &lt; evt.n_participants; ++i) {
            int pid      = evt.participant[i];
            int nevt_id  = user[pid].find_evt_idx(ename);
            user[pid].delete_event(nevt_id);
            ++cnt;
        }
        evt.init(-2);   // tombstone
    }
    else {
        evt.delete_pid(uid);
    }
    return cnt;
}

int changeEvent(int uid, char ename[], char cname[]) {
    int evt_id = user[uid].find_evt_idx(ename);
    if (evt_id == -1) {
        return 0;
    }

    int cnt = 1;
    auto  target = user[uid].event_info[evt_id];
    auto& evt    = event[target.gid][target.key];

    user[uid].delete_event(evt_id);
    addEvent(uid, cname, target.gid);

    if (target.is_master == true) {
        for (int i = 1; i &lt; evt.n_participants; ++i) {
            int pid     = evt.participant[i];
            int nevt_id = user[pid].find_evt_idx(ename);
            user[pid].delete_event(nevt_id);
            addEvent(pid, cname, target.gid);
            ++cnt;
        }
        evt.init(-2);   // tombstone
    }
    else {
        evt.delete_pid(uid);
    }
    return cnt;
}

int getCount(int uid) {
    return user[uid].n_events;
}

6 \(-1\) 판정
§3.2에서 보았듯이, 인접한 원소 중 같은 MSB를 가지는 쌍이 하나도 없으면 답은 \(-1\)이다.
bool all_msb_distinct = true;
for (int i = 2; i &lt;= n; ++i) {
    if ((31 - __builtin_clz(a[i])) == (31 - __builtin_clz(a[i-1]))) {
        all_msb_distinct = false;
        break;
    }
}
if (all_msb_distinct) { puts("-1"); continue; }






Tip대안 판정: 전체 XOR의 popcount



실전에서 popcount(a[1] ^ a[2] ^ ... ^ a[n]) == n 조건으로 판정하는 풀이도 AC를 받는다. 이는 모든 MSB가 서로 다를 때 XOR이 비트를 보존하는 성질에 의존하는데, 엄밀한 동치 증명은 쉽지 않으므로 MSB 직접 비교가 더 안전하다.

7 전체 풀이 코드
#include &lt;stdio.h&gt;

int a[100001];
int px[100001];

int main(void)
{
    int t;
    scanf("%d", &t);
    while (t--) {
        int n;
        scanf("%d", &n);
        px[0] = 0;
        for (int i = 1; i &lt;= n; ++i) {
            scanf("%d", &a[i]);
            px[i] = px[i - 1] ^ a[i];
        }

        // Case 1: N &gt;= 61 → 비둘기집 원리로 답 = 1
        if (n &gt;= 61) {
            puts("1");
            continue;
        }

        // Case 2: 모든 인접 MSB가 다르면 → 답 = -1
        bool all_distinct = true;
        for (int i = 2; i &lt;= n; ++i) {
            if ((31 - __builtin_clz(a[i])) == (31 - __builtin_clz(a[i - 1]))) {
                all_distinct = false;
                break;
            }
        }
        if (all_distinct) {
            puts("-1");
            continue;
        }

        // Case 3: N &lt;= 60 → O(N^3) 브루트포스
        int best = 100000;
        for (int i = 1; i &lt;= n; ++i) {
            for (int j = i; j &lt;= n; ++j) {
                int L = px[j] ^ px[i - 1];
                for (int k = j + 1; k &lt;= n; ++k) {
                    int R = px[k] ^ px[j];
                    if (L &gt; R) {
                        int cost = k - i - 1;
                        if (cost &lt; best) {
                            best = cost;
                        }
                        if (best == 1) {
                            goto done;
                        }
                    }
                }
            }
        }
        done:
        printf("%d\n", best);
    }
    return 0;
}

