6. 최상위 비트: 대칭이 깨지는 지점
lowbit과 달리 최상위 비트를 뽑는 두-연산짜리 산술 트릭은 존재하지 않는다. lowbit의 엔진은 캐리 전파인데, 덧셈의 캐리는 항상 낮은 자리에서 높은 자리로만 흐른다. 최상위 비트를 뽑으려면 정보가 높은 자리에서 낮은 자리로 흘러야 하고, 기본 연산 중 이를 수행하는 것은 오른쪽 시프트뿐이다.
방법 1 — 비트 스미어링(smearing): 시프트-OR로 최상위 1비트를 아래로 번지게 한 뒤, 연속 1 마스크에서 최상위만 남긴다.
unsigned int highbit(unsigned int x)
{
    x |= x &gt;&gt; 1;
    x |= x &gt;&gt; 2;
    x |= x &gt;&gt; 4;
    x |= x &gt;&gt; 8;
    x |= x &gt;&gt; 16;
    return x - (x &gt;&gt; 1);
}
각 단계가 “번진 폭”을 두 배로 늘리므로 32비트는 5단계면 충분하다.






Warning



마지막 줄을 \((x+1) \gg 1\)로 쓰면 \(x = \texttt{0xFFFFFFFF}\)일 때 \(x+1\)이 오버플로한다. 뺄셈 형태 \(x - (x \gg 1)\)이 안전하다.


방법 2 — 하드웨어 명령: __builtin_clz(x)는 leading zero 개수를 세는 컴파일러 내장 함수(인트린식)라 별도 헤더가 필요 없다. 단 \(x = 0\)이면 정의되지 않은 동작이며, 채점 환경의 컴파일러가 불명확하면 단순 루프가 가장 안전하다.
highbit이 실전에서 쓰이는 대표적인 곳은 BIT 위에서의 k번째 원소 탐색이다. 트리 최상단(\(n\) 이하의 가장 큰 2의 거듭제곱)에서 시작해 절반씩 내려오는 이진 탐색으로, 접두사 합이 처음으로 \(k\) 이상이 되는 인덱스를 \(O(\log n)\)에 찾는다.

Codes
#define MAX_N       (100'000)
#define MAX_TYPE    (1'000)

static int n_;
static int time_[MAX_N];
static long long bit_[MAX_N + 1];
static int head_[MAX_TYPE];
static int next_[MAX_N];

static void bit_add(int i, long long d)
{
    for (; i &lt;= n_; i += i & (-i)) bit_[i] += d;
}

static long long bit_sum(int i)
{
    long long s = 0;
    for (; i &gt; 0; i -= i & (-i)) s += bit_[i];
    return s;
}

void init(int N, int M, int mType[], int mTime[])
{
    n_ = N - 1;

    for (int i = 0; i &lt;= n_; ++i) bit_[i] = 0;
    for (int i = 0; i &lt; M; ++i) head_[i] = -1;

    for (int i = 0; i &lt; n_; ++i) {
        time_[i] = mTime[i];
        bit_add(i + 1, mTime[i]);
        next_[i] = head_[mType[i]];
        head_[mType[i]] = i;
    }
}

void destroy()
{
}

void update(int mID, int mNewTime)
{
    bit_add(mID + 1, (long long)mNewTime - time_[mID]);
    time_[mID] = mNewTime;
}

int updateByType(int mTypeID, int mRatio256)
{
    long long total = 0;
    for (int i = head_[mTypeID]; i != -1; i = next_[i]) {
        long long nt = ((long long)time_[i] * mRatio256) &gt;&gt; 8;
        bit_add(i + 1, nt - time_[i]);
        time_[i] = (int)nt;
        total += nt;
    }
    return (int)total;
}

int calculate(int mA, int mB)
{
    if (mA &gt; mB) { int t = mA; mA = mB; mB = t; }
    return (int)(bit_sum(mB) - bit_sum(mA));
}

5. open addressing 구현 시 주의할 점
벡터 \((x,y)\)를 키로 쓰는 해시테이블을 직접 구현할 때 두 가지 함정이 있었다.

5.1 종료 조건에 탐사 대상 값 자체를 쓰지 말 것
do {
    if (h_table[key].can_be_alloc(cp_a, cp_b)) return key;
} while (key = (key + 1) % MAX_TABLE);
이 패턴은 key가 선형 탐사 중 0으로 wraparound되는 순간 while 조건이 거짓이 되어 탐사가 충돌이 남아 있는데도 조기 종료된다. 실제로 무작위 \((at, cg)\) 쌍을 채워 load factor를 높이면, 탐사 거리가 길어질수록 거의 항상 이 조기 종료가 발생한다.






Warning



샘플 입력 \(N \le 5000\) 정도로는 테이블이 충분히 비어 있어 우연히 이 버그를 피해갈 수 있다. 종료 조건을 “다음 인덱스의 값”에 의존시키지 말고, 탐사 횟수를 별도 카운터로 제한해야 한다.


올바른 형태:
for (int tries = 0; tries &lt; MAX_TABLE; ++tries) {
    if (h_table[key].can_be_alloc(cp_a, cp_b)) return key;
    key = (key + 1) % MAX_TABLE;
}


5.2 초기화 오타는 우연히 무해할 수 있다
h_table[get_key(0, 0)].key_AT = h_table[0].key_CG = 0;
get_key(0, 0)이 실제로 가리키는 슬롯과 인덱스 0번 슬롯이 다를 수 있다. 이 경우 슬롯 0이 key_AT = -1, key_CG = 0인 반쪽 상태로 오염되지만, 바로 다음 줄에서 get_key(0,0)을 다시 호출해 정상 슬롯의 count를 세팅하므로 최종 정답에는 영향이 없다. 다만 이후 다른 입력에서 우연히 슬롯 0이 필요해지면 can_be_alloc의 비교 로직이 잘못된 결과를 낼 수 있는 잠재적 위험이 남는다.

7. Codes
#include &lt;stdio.h&gt;

unsigned long long int ans;
#define MAX_TABLE   (10007)
struct HashTable {
    int key_AT;
    int key_CG;
    int count;

    void init() {
        key_AT = key_CG = -1;
        count = 0;
    }

    bool can_be_alloc(int at, int cg) {
        if(key_AT == -1) {
            key_AT = at;
            key_CG = cg;

            return true;
        }
        return (key_AT == at && key_CG == cg);
    }
} h_table[MAX_TABLE];

int len;
char str[5001];

unsigned long get_key(long long at, long long cg)
{
    auto cp_a = at;
    auto cp_b = cg;
    at += 5000;
    cg += 5000;

    int key = ((at &lt;&lt; 14) + cg) % MAX_TABLE;
    do {
        if(h_table[key].can_be_alloc(cp_a, cp_b)) return key;
        key = (key + 1) % MAX_TABLE;
    } while(true);

    return 987654321ULL;
}

int main(void)
{
    int t;
    scanf("%d", &t);
    while(t--) {
        scanf("%d %s", &len, str);

        for(int i = 0; i &lt; MAX_TABLE; ++i) {
            h_table[i].init();
        }
        h_table[get_key(0, 0)].key_AT = h_table[0].key_CG = 0;
        h_table[get_key(0, 0)].count = 1;

        ans = 0;
        int at = 0;
        int cg = 0;
        for(int i = 0; i &lt; len; ++i) {
            switch(str[i]) {
                case 'A': ++at; break;
                case 'T': --at; break;
                case 'C': ++cg; break;
                case 'G': --cg; break;
                default: break;
            }

            auto key = get_key(at, cg);
            ans += h_table[key].count;
            ++h_table[key].count;
        }

        printf("%llu\n", ans);
    }
}

4 최종 구현
STL과 헤더 없이 동작한다.
extern void makeCookies(int mID);

#define MAX_CUTTER   (105)
#define MAX_SHAPE    (1005)
#define MAX_ORDER    (20005)      // 주문은 1번부터, 0 은 NULL
#define MAX_DAY      (30005)      // curDay(&lt;=15000) + daysLeft(&lt;=15000)

static int  curDay, tick, nCutter, nOrder;

/* ---------- 틀 ---------- */
static int  cutN[MAX_CUTTER];
static int  cutS[MAX_CUTTER][10];

/* ---------- 주문 ---------- */
static int  oShape[MAX_ORDER], oDay[MAX_ORDER], oTick[MAX_ORDER];
static bool oDead[MAX_ORDER];

/* 모양별 남아있는 주문 수 (checkRemain, 틀 가치 계산에 그대로 사용) */
static int  cnt[MAX_SHAPE];

/* 수령일별 주문 리스트 (도착 순서 = tick 오름차순 유지), 0 = NULL */
static int  dayHead[MAX_DAY], dayTail[MAX_DAY], nxt[MAX_ORDER];

/* ---------- 모양별 leftist heap : key = (수령일, 도착순서) ---------- */
static int  lc[MAX_ORDER], rc[MAX_ORDER], dist[MAX_ORDER], root[MAX_SHAPE];

static inline bool prior(int a, int b)          // a 가 b 보다 먼저 처리되어야 하는가
{
    if (oDay[a] != oDay[b]) return oDay[a] &lt; oDay[b];
    return oTick[a] &lt; oTick[b];
}

/* 오른쪽 경로 길이가 O(log n) 으로 보장되므로 재귀 깊이도 O(log n) */
static int meld(int a, int b)
{
    if (a == 0) return b;
    if (b == 0) return a;
    if (!prior(a, b)) { int t = a; a = b; b = t; }

    rc[a] = meld(rc[a], b);
    if (dist[lc[a]] &lt; dist[rc[a]]) { int t = lc[a]; lc[a] = rc[a]; rc[a] = t; }
    dist[a] = dist[rc[a]] + 1;
    return a;
}

static inline void hpush(int s, int v)
{
    lc[v] = rc[v] = 0;
    dist[v] = 1;
    root[s] = meld(root[s], v);
}

static inline int hpop(int s)                   // (수령일, 도착순서) 최소 주문
{
    int top = root[s];
    root[s] = meld(lc[top], rc[top]);
    return top;
}

/* ------------------------------------------------------------------ */
void init(void)
{
    curDay = 0; tick = 0; nCutter = 0; nOrder = 0;

    dist[0] = 0; lc[0] = 0; rc[0] = 0;                    // NULL 노드
    for (int s = 0; s &lt; MAX_SHAPE; ++s) { cnt[s] = 0; root[s] = 0; }
    for (int d = 0; d &lt; MAX_DAY; ++d)   { dayHead[d] = 0; dayTail[d] = 0; }
}

void addCookieCutter(int mID, int N, int mShapeList[])
{
    nCutter = mID;                                        // mID 는 1 부터 1 씩 증가
    cutN[mID] = N;
    for (int i = 0; i &lt; N; ++i) cutS[mID][i] = mShapeList[i];
}

void orderCookie(int mShape, int daysLeft)
{
    int id = ++nOrder;
    oShape[id] = mShape;
    oDay[id]   = curDay + daysLeft;
    oTick[id]  = ++tick;
    oDead[id]  = false;
    nxt[id]    = 0;

    int d = oDay[id];
    if (dayHead[d] == 0) dayHead[d] = id;
    else                 nxt[dayTail[d]] = id;
    dayTail[d] = id;

    hpush(mShape, id);
    ++cnt[mShape];
}

int checkRemain(int mShape)
{
    return cnt[mShape];
}

void newDay(void)
{
    ++curDay;

    int cur = dayHead[curDay];                  // 오늘이 수령일인 주문들, 도착 순
    while (cur != 0) {
        if (oDead[cur]) { cur = nxt[cur]; continue; }      // ① 가장 먼저 들어온 주문

        int shape = oShape[cur];

        /* ② 그 모양을 만들 수 있는 틀 중 남은 주문을 가장 많이 처리하는 틀.
              같은 모양은 중복해서 세지 않으므로 cnt[s] &gt; 0 인 모양의 개수가 곧 처리량 */
        int best = 0, bestCost = -1;
        for (int c = 1; c &lt;= nCutter; ++c) {
            bool has = false;
            int  cost = 0;
            for (int k = 0; k &lt; cutN[c]; ++k) {
                int s = cutS[c][k];
                if (s == shape) has = true;
                if (cnt[s] &gt; 0)  ++cost;
            }
            if (!has) continue;
            if (cost &gt; bestCost) { bestCost = cost; best = c; }   // 동점 -&gt; 작은 ID
        }
        if (best == 0) { cur = nxt[cur]; continue; }              // 문제상 발생하지 않음

        /* ③ 한 번 작업 */
        makeCookies(best);

        /* ④ 모양마다 (수령일, 도착순서) 가 최소인 주문 하나씩 처리 */
        for (int k = 0; k &lt; cutN[best]; ++k) {
            int s = cutS[best][k];
            if (cnt[s] &gt; 0) {
                int oi = hpop(s);
                oDead[oi] = true;
                --cnt[s];
            }
        }
        /* ⑤ cur 은 이번 작업에서 반드시 삭제되므로 다음 루프에서 건너뛴다 */
    }
    dayHead[curDay] = dayTail[curDay] = 0;
}

7. 4단계 — 답 집계
ll total = 0;
for (int i = 0; i &lt; q; ++i) {
    total += (ll)(i + 1) * query[i].ans;
}
출력 합의 상한 \(\sim Q^2 \cdot K \approx 1.25 \times 10^{17}\), long long 안에 충분히 들어옴. 음수 누적 (\(\mathrm{ans} = -1\)) 가능하니 signed long long.

Codes
#include &lt;stdio.h&gt;

using ll = long long;

int t, n, m, k, q;
constexpr int MAX_N     = 500'001;
constexpr int MAX_M     = 1'500'001;
constexpr int MAX_K     = 500'001;
constexpr int MAX_Q     = 500'001;
constexpr int MAX_NODES = 2 * MAX_N;
constexpr int INF       = 1'000'000'000;
constexpr ll  SAFE_BND  = 1'500'000'000LL;

struct Building {
    int x, y;
    void init(int _x, int _y) { x = _x; y = _y; }
} building[MAX_N];

struct Bridge {
    int v1, v2;
    int broken_time;
    ll  lb;
} bridge[MAX_M];

struct Winter { int v, h; } winter[MAX_K];
struct Query  { int src, dst; ll ans; } query[MAX_Q];

int v_evt_cnt  [MAX_N];
int v_evt_start[MAX_N + 1];
int evt_day [MAX_K];
ll  evt_z   [MAX_K];
ll  evt_max [MAX_K];
ll  temp_z  [MAX_N];
ll  temp_max[MAX_N];

int par_uf [MAX_NODES];
int kru_l  [MAX_NODES];
int kru_r  [MAX_NODES];
ll  kru_val[MAX_NODES];
int tot_nodes;

int find_uf(int x) {
    while (par_uf[x] != x) {
        par_uf[x] = par_uf[par_uf[x]];
        x = par_uf[x];
    }
    return x;
}

int  tarjan_par    [MAX_NODES];
int  tarjan_anc    [MAX_NODES];
char tarjan_visited[MAX_NODES];

int qry_head [MAX_NODES];
int qry_next [2 * MAX_Q];
int qry_other[2 * MAX_Q];
int qry_idx  [2 * MAX_Q];
int qry_count;

void qry_add(int u, int v, int qid) {
    qry_other[qry_count] = v;
    qry_idx  [qry_count] = qid;
    qry_next [qry_count] = qry_head[u];
    qry_head [u]         = qry_count++;
}

int tarjan_find(int x) {
    while (tarjan_par[x] != x) {
        tarjan_par[x] = tarjan_par[tarjan_par[x]];
        x = tarjan_par[x];
    }
    return x;
}

int dfs_stack[MAX_NODES];
int dfs_phase[MAX_NODES];

void tarjan_lca_all(int root) {
    int sp = 0;
    dfs_stack[sp] = root;
    dfs_phase[sp] = 0;
    ++sp;
    while (sp &gt; 0) {
        int u = dfs_stack[sp - 1];
        int p = dfs_phase[sp - 1];
        if (p == 0) {
            tarjan_par[u] = u;
            tarjan_anc[u] = u;
            dfs_phase[sp - 1] = 1;
            if (kru_l[u]) {
                dfs_stack[sp] = kru_l[u];
                dfs_phase[sp] = 0;
                ++sp;
                continue;
            }
            p = 1;
        }
        if (p == 1) {
            if (kru_l[u]) {
                tarjan_par[tarjan_find(kru_l[u])] = u;
                tarjan_anc[tarjan_find(u)] = u;
            }
            dfs_phase[sp - 1] = 2;
            if (kru_r[u]) {
                dfs_stack[sp] = kru_r[u];
                dfs_phase[sp] = 0;
                ++sp;
                continue;
            }
            p = 2;
        }
        if (p == 2) {
            if (kru_r[u]) {
                tarjan_par[tarjan_find(kru_r[u])] = u;
                tarjan_anc[tarjan_find(u)] = u;
            }
            tarjan_visited[u] = 1;
            for (int qe = qry_head[u]; qe != -1; qe = qry_next[qe]) {
                int v = qry_other[qe];
                if (tarjan_visited[v]) {
                    int qid = qry_idx[qe];
                    int la = tarjan_anc[tarjan_find(v)];
                    ll val = kru_val[la];
                    query[qid].ans = (val &gt;= INF) ? -1LL : val;
                }
            }
            --sp;
        }
    }
}

void _qsort(int p, int r) {
    if (p &gt;= r) return;
    int pivot = bridge[(p + r) &gt;&gt; 1].broken_time;
    int lt = p, gt = r, i = p;
    while (i &lt;= gt) {
        if (bridge[i].broken_time &gt; pivot) {
            auto tmp = bridge[lt];
            bridge[lt] = bridge[i];
            bridge[i] = tmp;
            ++lt; ++i;
        } else if (bridge[i].broken_time &lt; pivot) {
            auto tmp = bridge[gt];
            bridge[gt] = bridge[i];
            bridge[i] = tmp;
            --gt;
        } else {
            ++i;
        }
    }
    _qsort(p, lt - 1);
    _qsort(gt + 1, r);
}

void reset_state() {
    tot_nodes = 0;
    qry_count = 0;
}

int main(void) {
    scanf("%d", &t);
    while (t--) {
        reset_state();

        scanf("%d", &n);
        for (int i = 1; i &lt;= n; ++i) {
            int x, y;
            scanf("%d%d", &x, &y);
            building[i].init(x, y);
        }

        scanf("%d", &m);
        for (int i = 0; i &lt; m; ++i) {
            ll l;
            scanf("%d%d%lld", &bridge[i].v1, &bridge[i].v2, &l);
            ll dx = building[bridge[i].v1].x - building[bridge[i].v2].x;
            ll dy = building[bridge[i].v1].y - building[bridge[i].v2].y;
            bridge[i].lb          = l * l - dx * dx - dy * dy;
            bridge[i].broken_time = INF;
        }

        scanf("%d", &k);
        for (int i = 0; i &lt; k; ++i) {
            scanf("%d%d", &winter[i].v, &winter[i].h);
        }

        scanf("%d", &q);
        for (int i = 0; i &lt; q; ++i) {
            scanf("%d%d", &query[i].src, &query[i].dst);
        }

        for (int v = 1; v &lt;= n; ++v) v_evt_cnt[v] = 0;
        for (int i = 0; i &lt; k; ++i) v_evt_cnt[winter[i].v]++;
        v_evt_start[1] = 0;
        for (int v = 1; v &lt;= n; ++v) v_evt_start[v + 1] = v_evt_start[v] + v_evt_cnt[v];

        for (int v = 1; v &lt;= n; ++v) {
            v_evt_cnt[v] = 0;
            temp_z[v]   = 0;
            temp_max[v] = 0;
        }
        for (int i = 0; i &lt; k; ++i) {
            int v = winter[i].v;
            temp_z[v] += winter[i].h;
            ll abs_z = temp_z[v] &lt; 0 ? -temp_z[v] : temp_z[v];
            if (abs_z &gt; temp_max[v]) temp_max[v] = abs_z;
            int idx = v_evt_start[v] + v_evt_cnt[v];
            evt_day[idx] = i;
            evt_z  [idx] = temp_z[v];
            evt_max[idx] = temp_max[v];
            v_evt_cnt[v]++;
        }

        for (int e = 0; e &lt; m; ++e) {
            int u = bridge[e].v1;
            int v = bridge[e].v2;
            ll lb_e = bridge[e].lb;
            int cu = v_evt_cnt[u];
            int cv = v_evt_cnt[v];
            int su = v_evt_start[u];
            int sv = v_evt_start[v];

            if (cu == 0 && cv == 0) continue;

            if (cv == 0) {
                int lo = su, hi = su + cu;
                while (lo &lt; hi) {
                    int mid = (lo + hi) &gt;&gt; 1;
                    ll mval = evt_max[mid];
                    bool broken = (mval &gt; SAFE_BND) || (mval * mval &gt; lb_e);
                    if (broken) hi = mid;
                    else        lo = mid + 1;
                }
                if (lo &lt; su + cu) bridge[e].broken_time = evt_day[lo] + 1;
            } else if (cu == 0) {
                int lo = sv, hi = sv + cv;
                while (lo &lt; hi) {
                    int mid = (lo + hi) &gt;&gt; 1;
                    ll mval = evt_max[mid];
                    bool broken = (mval &gt; SAFE_BND) || (mval * mval &gt; lb_e);
                    if (broken) hi = mid;
                    else        lo = mid + 1;
                }
                if (lo &lt; sv + cv) bridge[e].broken_time = evt_day[lo] + 1;
            } else {
                ll z_u = 0, z_v = 0;
                int pu = su, pv = sv;
                int eu = su + cu, ev = sv + cv;
                while (pu &lt; eu || pv &lt; ev) {
                    int day;
                    if (pu &lt; eu && (pv == ev || evt_day[pu] &lt;= evt_day[pv])) {
                        z_u = evt_z[pu];
                        day = evt_day[pu];
                        pu++;
                    } else {
                        z_v = evt_z[pv];
                        day = evt_day[pv];
                        pv++;
                    }
                    ll diff = z_u - z_v;
                    if (diff * diff &gt; lb_e) {
                        bridge[e].broken_time = day + 1;
                        break;
                    }
                }
            }
        }

        _qsort(0, m - 1);

        for (int i = 1; i &lt;= 2 * n; ++i) par_uf[i] = i;
        for (int i = 1; i &lt;= n;     ++i) kru_l[i] = kru_r[i] = 0;
        tot_nodes = n;

        for (int i = 0; i &lt; m; ++i) {
            int ru = find_uf(bridge[i].v1);
            int rv = find_uf(bridge[i].v2);
            if (ru == rv) continue;
            int w = ++tot_nodes;
            kru_val[w] = bridge[i].broken_time;
            kru_l[w] = ru;
            kru_r[w] = rv;
            par_uf[ru] = w;
            par_uf[rv] = w;
        }

        for (int i = 1; i &lt;= tot_nodes; ++i) {
            qry_head[i] = -1;
            tarjan_visited[i] = 0;
        }
        for (int i = 0; i &lt; q; ++i) {
            qry_add(query[i].src, query[i].dst, i);
            qry_add(query[i].dst, query[i].src, i);
        }
        tarjan_lca_all(tot_nodes);

        ll total = 0;
        for (int i = 0; i &lt; q; ++i) {
            total += (ll)(i + 1) * query[i].ans;
        }
        printf("%lld\n", total);
    }
    return 0;
}

