#define MAX_RIDES   (100)
#define MAX_SIZE    (10'000)

int cur_time;

struct HeapArgument {
    int count;
    int priority;

    HeapArgument()
    {}

    HeapArgument(int _c, int _p) {
        count = _c;
        priority = _p;
    }

    bool operator &gt; (const HeapArgument& Other) {
        return (priority &gt; Other.priority);
    }
};

struct Heap {
    HeapArgument heap[MAX_SIZE];
    int size;
    int tot_cnt;

    void init() {
        size = 0;
        tot_cnt = 0;
    }

    void push(HeapArgument arg) {
        heap[size] = arg;
        tot_cnt += arg.count;

        int current = size;
        while (current &gt; 0 && heap[current] &gt; heap[(current - 1) / 2]) 
        {
            auto temp = heap[(current - 1) / 2];
            heap[(current - 1) / 2] = heap[current];
            heap[current] = temp;
            current = (current - 1) / 2;
        }

        ++size;
    }

    HeapArgument pop()
    {
        auto ret = heap[0];
        tot_cnt -= ret.count;
        --size;

        heap[0] = heap[size];

        int current = 0;
        while (current * 2 + 1 &lt; size)
        {
            int child;
            if (current * 2 + 2 == size)
            {
                child = current * 2 + 1;
            }
            else
            {
                child = heap[current * 2 + 1] &gt; heap[current * 2 + 2] ? current * 2 + 1 : current * 2 + 2;
            }

            if (heap[current] &gt; heap[child])
            {
                break;
            }

            auto temp = heap[current];
            heap[current] = heap[child];
            heap[child] = temp;

            current = child;
        }
        return ret;
    }
};

int n_rides;
struct Rides {
    int id;
    int duration;
    int cap;
    int end_time;

    bool is_on_operation() {
        return (end_time &gt; cur_time);
    }

    int get_highest_pri() {
        if(pque.size == 0) return 0;
        return pque.heap[0].priority;
    }

    void flush_queue() {
        if (end_time == -1) {
            return;
        }
        if (is_on_operation()) {
            return;
        }
        if (pque.size == 0) {
            return;
        }

        int factor = (cur_time - end_time + duration - 1) / duration;
        int need = (pque.tot_cnt + cap - 1) / cap;
        int runs = factor &lt; need ? factor : need;
        int tot_cap = runs * cap;

        int cnt = 0;
        while (tot_cap &gt; cnt) {
            if (pque.size == 0) {
                break;
            }
            int t_cnt = pque.heap[0].count;
            if (t_cnt + cnt &lt;= tot_cap) {
                cnt += t_cnt;
                pque.pop();
            }
            else {
                pque.heap[0].count -= (tot_cap - cnt);
                pque.tot_cnt -= (tot_cap - cnt);
                break;
            }
        }

        end_time += duration * runs;
    }

    void board_now() {
        if (is_on_operation()) {
            return;
        }
        if (pque.size == 0) {
            return;
        }

        int cnt = 0;
        while (cap &gt; cnt) {
            if (pque.size == 0) {
                break;
            }
            int t_cnt = pque.heap[0].count;
            if (t_cnt + cnt &lt;= cap) {
                cnt += t_cnt;
                pque.pop();
            }
            else {
                pque.heap[0].count -= (cap - cnt);
                pque.tot_cnt -= (cap - cnt);
                break;
            }
        }

        end_time = cur_time + duration;
    }

    Heap pque;
} rides[MAX_RIDES];

void init(int N, int mId[], int mDuration[], int mCapacity[]) {
    cur_time = 0;

    n_rides = N;
    for(int i = 0; i &lt; n_rides; ++i) {
        rides[i].id = mId[i];
        rides[i].duration = mDuration[i];
        rides[i].cap = mCapacity[i];
        rides[i].pque.init();
        rides[i].end_time = -1;
    }

    return;
}

int get_ride_id(int m_id) {
    for(int i = 0; i &lt; n_rides; ++i) {
        if(rides[i].id == m_id) return i;
    }

    return -1;
}

int add(int tStamp, int mId, int mNum, int mPriority) {
    cur_time = tStamp;

    HeapArgument arg(mNum, mPriority);

    int r_id = get_ride_id(mId);
    auto& target = rides[r_id];

    target.flush_queue();
    target.pque.push(arg);

    if(target.end_time == -1) {
        target.end_time = cur_time;
    }

    target.board_now();

    return target.get_highest_pri();
}

void search(int tStamp, int mCount, int mId[], int mWait[]) {
    cur_time = tStamp;

    for(int i = 0; i &lt; n_rides; ++i) {
        rides[i].flush_queue();
        rides[i].board_now();
    }

    for(int i = 0; i &lt; 10; ++i) {
        mId[i] = mWait[i] = -1;
    }

    for(int i = 0; i &lt; n_rides; ++i) {
        int j = mCount - 1;
        for(;j &gt;= 0;) {
            bool cond1 = (rides[i].pque.tot_cnt &gt; mWait[j]);
            bool cond2 = (rides[i].pque.tot_cnt == mWait[j]) && (rides[i].id &gt; mId[j]);
            if(cond1 || cond2) {
                --j;
            }
            else break;
        }
        for(int k = mCount - 2; k &gt;= j + 1; --k) {
            mId[k + 1] = mId[k];
            mWait[k + 1] = mWait[k];
        }
        if(j + 1 &lt;= mCount - 1) {
            mId[j + 1] = rides[i].id;
            mWait[j + 1] = rides[i].pque.tot_cnt;
        }
    }

    return;
}

5.6 Indicator random variable 정의
다음 지시변수를 정의하자.
\[
X_{ij} = I\{A[j] \text{ falls in bucket } i\}
\]
즉,
\[
X_{ij} =
\begin{cases}
1 & \text{if } A[j] \text{가 bucket } i \text{에 들어가면}, \\
0 & \text{otherwise.}
\end{cases}
\]
그러면 bucket \(i\)의 원소 수는 \[
n_i = \sum_{j=0}^{n-1} X_{ij}
\] 이다.

4.4 Autocorrelation coefficient
The correlation coefficient is the covariance divided by the product of standard deviations (not the product of variances). \[
\rho_N(t_1,t_2)=\frac{\mathrm{Cov}(N_{t_1},N_{t_2})}{\sqrt{\mathrm{Var}N_{t_1}}\sqrt{\mathrm{Var}N_{t_2}}}
=\frac{\lambda_0\min(t_1,t_2)}{\sqrt{\lambda_0t_1}\sqrt{\lambda_0t_2}}
=\frac{\min(t_1,t_2)}{\sqrt{t_1t_2}}.
\] If we denote it as \(t_1&lt;t_2\) and write the molecule as \(t_1=\sqrt{t_1^2}\), \[
\frac{t_1}{\sqrt{t_1t_2}}=\sqrt{\frac{t_1^2}{t_1t_2}}=\sqrt{\frac{t_1}{t_2}}
\quad\Longrightarrow\quad
\boxed{\rho_N(t_1,t_2)=\sqrt{\frac{\min(t_1,t_2)}{\max(t_1,t_2)}}.}
\]
Confirm. If it is \(t_1=t_2\), then it is \(\rho_N=1\) (perfectly correlated since it is the same point in time). If it is \(t_1\to 0\) or moves away to \(t_2\to\infty\), then it is \(\rho_N\to 0\). Therefore, it is always within the \([0,1]\) range.

MDP는 완전 관측 가능(fully observable) 환경을 형식화하는 표준 틀이다. “현재 상태가 미래를 결정하는 데 필요한 모든 정보를 담고 있다”는 Markov 성질 위에, 보상(reward) 과 행동(action) 을 차례로 얹어 나가는 구조를 갖는다.

\underbrace{\langle S, P\rangle}_{\text{Markov Process}}
\;\xrightarrow{+\,R,\;\gamma}\;
\underbrace{\langle S, P, R, \gamma\rangle}_{\text{MRP}}
\;\xrightarrow{+\,A}\;
\underbrace{\langle S, A, P, R, \gamma\rangle}_{\text{MDP}}







중요한 문장으로 압축한 핵심



MDP에 정책 \pi를 고정하면 즉시 MRP가 되고, MRP는 다시 Markov Process가 된다. 따라서 정책 평가(evaluation)는 언제나 “유도된 MRP의 가치 계산”으로 환원된다.

5.3 최적 정책 찾기
q_*를 알면 즉시 greedy하게 결정적(deterministic) 정책을 얻는다.

\pi_*(a\mid s) =
\begin{cases}
1 & \text{if } a = \arg\max_{a\in A} q_*(s,a)\\
0 & \text{otherwise}
\end{cases}







중요



결정적 최적 정책은 항상 존재한다. 즉 q_*만 구하면 MDP는 끝난다.

