#include &lt;bits/stdc++.h&gt;
using namespace std;
typedef long long ll;

const int MAXP = 100001;  // prices in [1, MAXP-1]

struct Node {
    ll liters;
    ll cost;
};
Node seg[4 * MAXP];

void update(int node, int l, int r, int idx, ll dl) {
    if (l == r) {
        seg[node].liters += dl;
        seg[node].cost   += dl * (ll)l;   // l == price at the leaf
        return;
    }
    int mid = (l + r) &gt;&gt; 1;
    if (idx &lt;= mid) {
        update(node &lt;&lt; 1, l, mid, idx, dl);
    } else {
        update(node &lt;&lt; 1 | 1, mid + 1, r, idx, dl);
    }
    seg[node].liters = seg[node &lt;&lt; 1].liters + seg[node &lt;&lt; 1 | 1].liters;
    seg[node].cost   = seg[node &lt;&lt; 1].cost   + seg[node &lt;&lt; 1 | 1].cost;
}

// min cost to obtain exactly L liters from active liquids; -1 if pool insufficient
ll query(int node, int l, int r, ll L) {
    if (seg[node].liters &lt; L) {
        return -1;
    }
    if (l == r) {
        return L * (ll)l;
    }
    int mid = (l + r) &gt;&gt; 1;
    if (seg[node &lt;&lt; 1].liters &gt;= L) {
        return query(node &lt;&lt; 1, l, mid, L);
    } else {
        return seg[node &lt;&lt; 1].cost
             + query(node &lt;&lt; 1 | 1, mid + 1, r, L - seg[node &lt;&lt; 1].liters);
    }
}

