            }

            memset(seg, 0, sizeof(seg));

            for (int k = 0; k &lt; n; ++k) {
                int p   = liq[k][1];
                int lit = liq[k][2];
                update(1, 1, MAXP - 1, p, lit);

                for (int j : bucket[k]) {
                    ll c = query(1, 1, MAXP - 1, L[j]);
                    if (c != -1 && c &lt;= G[j]) {
                        hi[j] = k;
                    } else {
                        lo[j] = k + 1;
                    }
                }
            }
        }

        for (int j = 0; j &lt; m; ++j) {
            if (j &gt; 0) {
                putchar(' ');
            }
            int k = lo[j];
            if (k &gt;= n) {
                printf("-1");
            } else {
                printf("%d", liq[k][0]);
            }
        }
        putchar('\n');
    }
    return 0;
}

