static int getIterCount(int timeCnt)
{
    if (timeCnt &lt; 100) return 120;
    if (timeCnt &lt; 200) return 40;
    if (timeCnt &lt; 300) return 25;
    if (timeCnt &lt; 400) return 18;
    if (timeCnt &lt; 500) return 12;
