static void qsT(int first, int last)
{
    int pivot;
    int i;
    int j;
    TimeInfo temp;

    if (first &lt; last)
    {
        pivot = first;
        i = first;
        j = last;

        while (i &lt; j)
        {
            while (timeInfo[i].sizeSum &lt;= timeInfo[pivot].sizeSum && i &lt; last)
            {
                i++;
            }
            while (timeInfo[j].sizeSum &gt; timeInfo[pivot].sizeSum)
            {
                j--;
            }
            if (i &lt; j)
            {
                temp = timeInfo[i];
                timeInfo[i] = timeInfo[j];
                timeInfo[j] = temp;
            }
        }

        temp = timeInfo[pivot];
        timeInfo[pivot] = timeInfo[j];
        timeInfo[j] = temp;

        qsT(first, j - 1);
        qsT(j + 1, last);
    }
}

static void qsP(int first, int last)
{
    int pivot;
    int i;
    int j;
    int temp;

    if (first &lt; last)
    {
        pivot = first;
        i = first;
        j = last;

        while (i &lt; j)
        {
            while (T[placed[i]].offset &lt;= T[placed[pivot]].offset && i &lt; last)
            {
                i++;
            }
            while (T[placed[j]].offset &gt; T[placed[pivot]].offset)
            {
                j--;
            }
            if (i &lt; j)
            {
                temp = placed[i];
                placed[i] = placed[j];
                placed[j] = temp;
            }
        }

        temp = placed[pivot];
        placed[pivot] = placed[j];
        placed[j] = temp;

        qsP(first, j - 1);
        qsP(j + 1, last);
    }
}

static void qsNp(int first, int last)
{
    int pivot;
    int i;
    int j;
    int temp;

    if (first &lt; last)
    {
        pivot = first;
        i = first;
        j = last;

        while (i &lt; j)
        {
            while (T[notPlaced[i]].size &lt;= T[notPlaced[pivot]].size && i &lt; last)
            {
                i++;
            }
            while (T[notPlaced[j]].size &gt; T[notPlaced[pivot]].size)
            {
                j--;
            }
            if (i &lt; j)
            {
                temp = notPlaced[i];
                notPlaced[i] = notPlaced[j];
                notPlaced[j] = temp;
            }
        }

        temp = notPlaced[pivot];
        notPlaced[pivot] = notPlaced[j];
        notPlaced[j] = temp;

        qsNp(first, j - 1);
        qsNp(j + 1, last);
    }
}

static void slist_step(int time, int left)
{
    int k = 0;

    for (int i = 0; i &lt; slc; ++i)
    {
        int id = slist[i];
        if (left ? (T[id].start &lt;= time) : (T[id].end &gt; time))
        {
            tmpl[k++] = id;
        }
    }

    int ac = 0;
    for (int i = 0; i &lt; nwc; ++i)
    {
        int id = newly[i];
        if (left ? (T[id].start &lt;= time) : (T[id].end &gt; time))
        {
            int p = ac;
            while (p &gt; 0 && T[newly[p - 1]].offset &gt; T[id].offset)
            {
                newly[p] = newly[p - 1];
                --p;
            }
            newly[p] = id;
            ++ac;
        }
    }

    int a = 0, b = 0;
    slc = 0;
    while (a &lt; k || b &lt; ac)
    {
        if (b &gt;= ac || (a &lt; k && T[tmpl[a]].offset &lt;= T[newly[b]].offset))
            slist[slc++] = tmpl[a++];
        else
            slist[slc++] = newly[b++];
    }

    nwc = 0;
}

static void placeAtTime(int time)
{
    npcnt = 0;
    fcnt = 0;

    for (int i = 0; i &lt; timeCnt[time]; ++i)
    {
        if (!T[timeBucket[time][i]].placed)
        {
            notPlaced[npcnt++] = timeBucket[time][i];
        }
    }

    if (npcnt == 0) return;

    int prev = 0;

    for (int i = 0; i &lt; slc; ++i)
    {
        int cur = T[slist[i]].offset;
        int sz = cur - prev;

        if (sz &gt; 0) F[fcnt++] = { prev, cur, sz, false };

        prev = cur + T[slist[i]].size;
    }

    qsNp(0, npcnt - 1);

    for (int i = npcnt - 1; i &gt;= 0; --i)
    {
        auto& t = T[notPlaced[i]];

        int minRem = 1000000000;
        int fidx = -1;

        for (int j = 0; j &lt; fcnt; ++j)
        {
            if (F[j].taken) continue;
            if (t.size &gt; F[j].size) continue;

            int alignedStart = alignUp(F[j].start, t.align);
            int alignedSize = F[j].end - alignedStart;

            if (t.size &gt; alignedSize) continue;

            int rem = alignedSize - t.size;

            if (rem &lt; minRem)
            {
                minRem = rem;
                fidx = j;
            }
        }

        if (fidx != -1)
        {
            t.offset = alignUp(F[fidx].start, t.align);
            t.placed = true;
            F[fidx].taken = true;
        }
        else
        {
            prev = alignUp(prev, t.align);
            t.offset = prev;
            t.placed = true;
            prev += t.size;
            if (prev &gt; mxPeak) mxPeak = prev;
        }

        newly[nwc++] = notPlaced[i];
    }
}

static void slist_init(int mxSzTime, int time, int left)
{
    pcnt = 0;

    for (int i = 0; i &lt; timeCnt[mxSzTime]; ++i)
    {
        int id = timeBucket[mxSzTime][i];
        if (left ? (T[id].start &lt;= time) : (T[id].end &gt; time))
        {
            placed[pcnt++] = id;
        }
    }

    qsP(0, pcnt - 1);

    slc = 0;
    for (int i = 0; i &lt; pcnt; ++i) slist[slc++] = placed[i];
    nwc = 0;
}

static int ref_construct(int mTensorCount, const Tensor mTensors[], int mOffsets[])
{
    mxTime = 0;
    minMxPeak = 1000000000;

    for (int i = 0; i &lt; MAX_TIME; ++i)
    {
        timeCnt[i] = 0;
        timeInfo[i] = { i, 0 };

        for (int j = 0; j &lt; 4; ++j)
        {
            timeCntByType[i][j] = 0;
        }
    }

    for (int i = 0; i &lt; mTensorCount; ++i)
    {
        T[i].init(mTensors[i]);

        for (int j = T[i].start; j &lt; T[i].end; ++j)
        {
            timeBucket[j][timeCnt[j]++] = i;
            timeInfo[j].sizeSum += T[i].size;
            ++timeCntByType[j][alignToType(T[i].align)];
        }

        if (T[i].end &gt; mxTime) mxTime = T[i].end;
    }

    qsT(0, mxTime - 1);

    int prevMxSz = -1;
    ccnt = 0;

    for (int i = mxTime - 1; i &gt;= 0; --i)
    {
        if (prevMxSz == -1 || prevMxSz != timeInfo[i].sizeSum)
        {
            candStartTime[ccnt++] = timeInfo[i].time;

            if (ccnt == MAX_TIME_ITER) break;
        }
    }

    int iterCount = getIterCount(timeCnt[candStartTime[0]]);
    iterCount = iterCount * 4 / 5;
    if (iterCount &lt; 4) iterCount = 4;
    if (iterCount &gt; g_anchor_cap_) iterCount = g_anchor_cap_;
    if (iterCount &gt; ccnt) iterCount = ccnt;
    int last_imp = 0;
    for (int iter = 0; iter &lt; iterCount; ++iter)
    {
        if (iter - last_imp &gt; 8) break;
        mxPeak = 0;

        for (int i = 0; i &lt; mTensorCount; ++i)
        {
            T[i].offset = 0;
            T[i].placed = false;
        }

        int mxSzTime = candStartTime[iter];
        int placeCnt = 0;
        int cur = 0;

        while (placeCnt != timeCnt[mxSzTime])
        {
            int targetType = 0;
            if (timeCntByType[mxSzTime][1] &gt; 0) targetType = 1;
            if (timeCntByType[mxSzTime][2] &gt; 0) targetType = 2;
            if (timeCntByType[mxSzTime][3] &gt; 0) targetType = 3;

            int targetAlign = typeToAlign(targetType);

            int minF = 999;
            int tidx = -1;
            int sidx = -1;
            int tempidx = -1;

            for (int i = 0; i &lt; timeCnt[mxSzTime]; ++i)
            {
                auto& t = T[timeBucket[mxSzTime][i]];

                if (t.placed) continue;

                if (t.align == targetAlign)
                {
                    tempidx = timeBucket[mxSzTime][i];

                    for (int j = 0; j &lt; timeCnt[mxSzTime]; ++j)
                    {
                        auto& s = T[timeBucket[mxSzTime][j]];

                        if (s.placed) continue;
                        if (i == j) continue;

                        int f1 = alignUp(t.size, s.align) - t.size;
                        int f2 = alignUp(alignUp(t.size, s.align) + s.size, t.align) - alignUp(t.size, s.align) - s.size;

                        if (f1 + f2 &lt; minF)
                        {
                            minF = f1 + f2;
                            tidx = timeBucket[mxSzTime][i];
                            sidx = timeBucket[mxSzTime][j];
                        }
                    }
                }
            }

            if (minF != 999)
            {
                ++placeCnt;
                cur = alignUp(cur, T[tidx].align);
                T[tidx].offset = cur;
                T[tidx].placed = true;
                --timeCntByType[mxSzTime][alignToType(T[tidx].align)];
                cur += T[tidx].size;

                ++placeCnt;
                cur = alignUp(cur, T[sidx].align);
                T[sidx].offset = cur;
                T[sidx].placed = true;
                --timeCntByType[mxSzTime][alignToType(T[sidx].align)];
                cur += T[sidx].size;

                continue;
            }

            if (tempidx != -1)
            {
                ++placeCnt;
                cur = alignUp(cur, T[tempidx].align);
                T[tempidx].offset = cur;
                T[tempidx].placed = true;
                --timeCntByType[mxSzTime][alignToType(T[tempidx].align)];
                cur += T[tempidx].size;
            }
        }

        mxPeak = cur;

        if (mxSzTime - 1 &gt;= 0)
        {
            slist_init(mxSzTime, mxSzTime - 1, 1);

            for (int tt = mxSzTime - 1; tt &gt;= 0; --tt)
            {
                slist_step(tt, 1);
                placeAtTime(tt);
            }
        }

        if (mxSzTime + 1 &lt;= mxTime)
        {
            slist_init(mxSzTime, mxSzTime + 1, 0);

            for (int tt = mxSzTime + 1; tt &lt;= mxTime; ++tt)
            {
                slist_step(tt, 0);
                placeAtTime(tt);
            }
        }

        if (mxPeak &lt; minMxPeak)
        {
            last_imp = iter;
            minMxPeak = mxPeak;

            for (int i = 0; i &lt; mTensorCount; ++i)
            {
                bestOffsets[i] = T[i].offset;
            }
        }
    }

    for (int i = 0; i &lt; mTensorCount; ++i)
    {
        mOffsets[i] = bestOffsets[i];
    }

    return minMxPeak;
}


