static void sort_idx(int *idx, int lo0, int hi0)
{
    int lo_st[64], hi_st[64];
    int top = 0;

    if (hi0 - lo0 &lt; 1) return;
    lo_st[0] = lo0;
    hi_st[0] = hi0;
    top = 1;

    while (top &gt; 0)
    {
        --top;
        int lo = lo_st[top];
        int hi = hi_st[top];

        while (lo &lt; hi)
        {
            if (hi - lo &lt; 12)
            {
                for (int j = lo + 1; j &lt;= hi; ++j)
                {
                    int ki = idx[j];
                    long long kv = key_[ki];
                    int i = j - 1;
                    while (i &gt;= lo && key_[idx[i]] &gt; kv)
                    {
                        idx[i + 1] = idx[i];
                        --i;
                    }
                    idx[i + 1] = ki;
                }
                break;
            }

            int mid = lo + (hi - lo) / 2;
            long long pa = key_[idx[lo]], pb = key_[idx[mid]], pc = key_[idx[hi]];
            long long pv;
            if (pa &lt; pb)
            {
                if (pb &lt; pc) pv = pb;
                else pv = (pa &lt; pc) ? pc : pa;
            }
            else
            {
                if (pa &lt; pc) pv = pa;
                else pv = (pb &lt; pc) ? pc : pb;
            }

            int lt = lo, gt = hi, i = lo;
            while (i &lt;= gt)
            {
                long long cv = key_[idx[i]];
                if (cv &lt; pv)
                {
                    int tv = idx[lt]; idx[lt] = idx[i]; idx[i] = tv;
                    ++lt; ++i;
                }
                else if (cv &gt; pv)
                {
                    int tv = idx[gt]; idx[gt] = idx[i]; idx[i] = tv;
                    --gt;
                }
                else ++i;
            }

            if (lt - lo &gt; hi - gt)
            {
                lo_st[top] = lo; hi_st[top] = lt - 1; ++top;
                lo = gt + 1;
            }
            else
            {
                lo_st[top] = gt + 1; hi_st[top] = hi; ++top;
                hi = lt - 1;
            }
        }
    }
}

static void radix_pass(int *src_so, int *src_se, int *dst_so, int *dst_se, int m, int shift)
{
    for (int b = 0; b &lt; 256; ++b) radix_cnt_[b] = 0;
    for (int x = 0; x &lt; m; ++x) ++radix_cnt_[(src_so[x] &gt;&gt; shift) & 255];

    int acc = 0;
    for (int b = 0; b &lt; 256; ++b)
    {
        int c = radix_cnt_[b];
        radix_cnt_[b] = acc;
        acc += c;
    }

    for (int x = 0; x &lt; m; ++x)
    {
        int p = radix_cnt_[(src_so[x] &gt;&gt; shift) & 255]++;
        dst_so[p] = src_so[x];
        dst_se[p] = src_se[x];
    }
}

static void sort_segs(int m)
{
    if (m &lt; 48)
    {
        for (int j = 1; j &lt; m; ++j)
        {
            int ko = seg_so_[j], ke = seg_se_[j];
            int i = j - 1;
            while (i &gt;= 0 && seg_so_[i] &gt; ko)
            {
                seg_so_[i + 1] = seg_so_[i];
                seg_se_[i + 1] = seg_se_[i];
                --i;
            }
            seg_so_[i + 1] = ko;
            seg_se_[i + 1] = ke;
        }
        return;
    }

    int mx = 0;
    for (int x = 0; x &lt; m; ++x)
        if (seg_so_[x] &gt; mx) mx = seg_so_[x];

    radix_pass(seg_so_, seg_se_, tmp_so_, tmp_se_, m, 0);
    radix_pass(tmp_so_, tmp_se_, seg_so_, seg_se_, m, 8);

    if (mx &lt; (1 &lt;&lt; 16)) return;

    radix_pass(seg_so_, seg_se_, tmp_so_, tmp_se_, m, 16);

    if (mx &lt; (1 &lt;&lt; 24))
    {
        for (int x = 0; x &lt; m; ++x)
        {
            seg_so_[x] = tmp_so_[x];
            seg_se_[x] = tmp_se_[x];
        }
        return;
    }

    radix_pass(tmp_so_, tmp_se_, seg_so_, seg_se_, m, 24);
}

static void build_adjacency(int n, const Tensor *t)
{
    long long total = 0;

    for (int i = 0; i &lt; n; ++i) deg_[i] = 0;

    for (int i = 0; i &lt; n; ++i)
    {
        int si = t[i].start, ei = t[i].end;
        for (int j = i + 1; j &lt; n; ++j)
        {
            if (si &lt; t[j].end && t[j].start &lt; ei)
            {
                ++deg_[i];
                ++deg_[j];
                total += 2;
            }
        }
    }

    adj_total_ = total;

    if (total &gt; ADJ_CAP)
    {
        adj_ok_ = 0;
        return;
    }

    adj_ok_ = 1;
    head_[0] = 0;
    for (int i = 1; i &lt; n; ++i) head_[i] = head_[i - 1] + deg_[i - 1];
    for (int i = 0; i &lt; n; ++i) pos_[i] = head_[i];

    for (int i = 0; i &lt; n; ++i)
    {
        int si = t[i].start, ei = t[i].end;
        for (int j = i + 1; j &lt; n; ++j)
        {
            if (si &lt; t[j].end && t[j].start &lt; ei)
            {
                adj_[pos_[i]++] = j;
                adj_[pos_[j]++] = i;
            }
        }
    }
}

static int lowest_fit_h(int n, const Tensor *t, const int *off, int i, int use_placed, long long hint)
{
    int a = t[i].align;
    int sz = t[i].size;
    long long bound = (hint &gt;= 0) ? hint + sz + 1 : 0x3fffffffLL;

    while (1)
    {
        int m2 = 0;
