        sort_segs(m2);

        int cand = 0;

        for (int x = 0; x &lt; m2; ++x)
        {
            if ((long long)cand + sz &lt;= seg_so_[x]) break;
            if (seg_se_[x] &gt; cand) cand = align_up_v(seg_se_[x], a);
        }

        if ((long long)cand + sz &lt;= bound || skipped == 0) return cand;

        bound *= 4;
    }
}

static int lowest_fit(int n, const Tensor *t, const int *off, int i, int use_placed)
{
    return lowest_fit_h(n, t, off, i, use_placed, -1);
}

static int best_fit(int n, const Tensor *t, const int *off, int i, long long cap)
{
    int m = 0;

    if (adj_ok_)
    {
        int p_end = head_[i] + deg_[i];
        for (int p = head_[i]; p &lt; p_end; ++p)
        {
            int j = adj_[p];
            if (placed_[j])
            {
                seg_so_[m] = off[j];
                seg_se_[m] = off[j] + t[j].size;
                ++m;
            }
        }
    }
    else
    {
        for (int j = 0; j &lt; n; ++j)
        {
            if (j == i) continue;
            if (!placed_[j]) continue;
            if (t[i].start &lt; t[j].end && t[j].start &lt; t[i].end)
            {
                seg_so_[m] = off[j];
                seg_se_[m] = off[j] + t[j].size;
                ++m;
            }
        }
    }

    sort_segs(m);

    int a = t[i].align;
    int sz = t[i].size;
    int cand = 0;
    int best_st = -1;
    long long best_waste = 0x3fffffffffffffffLL;

    for (int x = 0; x &lt; m; ++x)
    {
        if ((long long)cand + sz &lt;= seg_so_[x])
        {
            long long waste = (long long)seg_so_[x] - cand - sz;
            if (waste &lt; best_waste)
            {
                best_waste = waste;
                best_st = cand;
            }
        }

        if (seg_se_[x] &gt; cand)
        {
            int nc = align_up_v(seg_se_[x], a);
            if (nc &gt; cand) cand = nc;
        }
    }

    if (best_st &lt; 0) return cand;
    if ((long long)cand + sz &lt;= cap) return cand;
    return best_st;
}

static long long place_order(int n, const Tensor *t, int *off, int *peak_tensor, long long abort_peak)
{
    long long peak = 0;
    int pt = -1;

    for (int i = 0; i &lt; n; ++i) placed_[i] = 0;

    for (int k = 0; k &lt; n; ++k)
    {
        int i = ord_[k];
        int cand = lowest_fit(n, t, off, i, 1);

        off[i] = cand;
        placed_[i] = 1;

        long long top = (long long)cand + t[i].size;
        if (top &gt; peak)
        {
            peak = top;
            pt = i;

            if (peak &gt;= abort_peak)
            {
                if (peak_tensor) *peak_tensor = pt;
                return 0x3fffffffffffffffLL;
            }
        }
    }

    if (peak_tensor) *peak_tensor = pt;
    return peak;
}

static long long lower_to_fixpoint(int n, const Tensor *t, int *off, int max_rounds)
{
    for (int r = 0; r &lt; max_rounds; ++r)
    {
        for (int i = 0; i &lt; n; ++i)
        {
            key_[i] = -(((long long)off[i] &lt;&lt; 13) | i);
            ord2_[i] = i;
        }
        sort_idx(ord2_, 0, n - 1);

        int changed = 0;

        for (int k = 0; k &lt; n; ++k)
        {
            int i = ord2_[k];
            int cand = lowest_fit_h(n, t, off, i, 0, off[i]);

            if (cand &lt; off[i])
            {
                off[i] = cand;
                changed = 1;
            }
        }

        if (!changed) break;
    }

    long long peak = 0;
    for (int i = 0; i &lt; n; ++i)
    {
        long long top = (long long)off[i] + t[i].size;
        if (top &gt; peak) peak = top;
    }

    return peak;
}

static void find_bottleneck_alive(int n, const Tensor *t)
{
    for (int j = 0; j &lt; TIME_CAP; ++j) load_[j] = 0;

    for (int i = 0; i &lt; n; ++i)
    {
        load_[t[i].start] += t[i].size;
        load_[t[i].end] -= t[i].size;
    }

    long long cur = 0, best = -1;
    int best_t = 0;

    for (int j = 0; j &lt; TIME_CAP; ++j)
    {
        cur += load_[j];
        if (cur &gt; best)
        {
            best = cur;
            best_t = j;
        }
    }

    for (int i = 0; i &lt; n; ++i)
    {
        alive_[i] = (t[i].start &lt;= best_t && best_t &lt; t[i].end) ? 1 : 0;
    }
}

static int hole_alloc_node(void)
{
    if (h_free_top_ &gt; 0) return h_free_[--h_free_top_];
    return h_bump_++;
}

static void hole_release_node(int x)
{
    h_free_[h_free_top_++] = x;
}

static long long sweep_construct(int n, const Tensor *t, int *off, int policy, int noise, long long cap)
{
    h_free_top_ = 0;
    h_bump_ = 2;

    int hd = 0, tl = 1;
    h_next_[hd] = tl;
    h_prev_[tl] = hd;
    h_prev_[hd] = -1;
    h_next_[tl] = -1;

    int first = hole_alloc_node();
    h_lo_[first] = 0;
    h_hi_[first] = INF_HI;
    h_prev_[first] = hd;
    h_next_[first] = tl;
    h_next_[hd] = first;
    h_prev_[tl] = first;

    long long peak = 0;
    int f = 0;

    for (int k = 0; k &lt; n; ++k)
    {
        int i = by_start_[k];

        while (f &lt; n && t[by_end_[f]].end &lt;= t[i].start)
        {
            int j = by_end_[f];
            ++f;

            int lo = off[j];
            int hi = off[j] + t[j].size;

            int cur = h_next_[hd];
            while (cur != tl && h_lo_[cur] &lt; lo) cur = h_next_[cur];

            int pv = h_prev_[cur];
            int merged = 0;

            if (pv != hd && h_hi_[pv] == lo)
            {
                h_hi_[pv] = hi;
                merged = pv;
            }

            if (merged && cur != tl && h_lo_[cur] == hi)
            {
                h_hi_[merged] = h_hi_[cur];
                h_next_[merged] = h_next_[cur];
                h_prev_[h_next_[cur]] = merged;
                hole_release_node(cur);
            }
            else if (!merged && cur != tl && h_lo_[cur] == hi)
            {
                h_lo_[cur] = lo;
            }
            else if (!merged)
            {
                int nn = hole_alloc_node();
                h_lo_[nn] = lo;
                h_hi_[nn] = hi;
                h_prev_[nn] = pv;
                h_next_[nn] = cur;
                h_next_[pv] = nn;
                h_prev_[cur] = nn;
            }
        }

        int a = t[i].align;
        int sz = t[i].size;

        int best_node = -1;
        int best_st = 0;
        long long best_score = 0x3fffffffffffffffLL;

        int cur = h_next_[hd];
        while (cur != tl)
        {
            int st = align_up_v(h_lo_[cur], a);

            if (h_hi_[cur] == INF_HI || (long long)st + sz &lt;= h_hi_[cur])
            {
                long long sc;
                int in_cap = (cap &lt; 0) || ((long long)st + sz &lt;= cap);

                if (h_hi_[cur] == INF_HI)
                {
                    if (cap &gt;= 0 && in_cap)
                        sc = ((cap - st - sz) &lt;&lt; 25) + st;
                    else
                        sc = 0x3ffffffffffffffeLL;
                }
                else if (policy == 0)
                {
                    sc = st;
                }
                else if (policy == 1)
                {
                    sc = ((long long)(h_hi_[cur] - st - sz) &lt;&lt; 25) + st;
                }
                else
                {
                    sc = ((long long)(h_hi_[cur] - st - sz + 2 * (st - h_lo_[cur])) &lt;&lt; 25) + st;
                }

                if (!in_cap && sc &lt; 0x3ffffffffffffffeLL)
                {
                    sc = 0x2000000000000000LL + st;
                }

                if (noise &gt; 0 && sc &lt; 0x2000000000000000LL)
                {
                    sc += rnd_next() % noise;
                }

                if (sc &lt; best_score)
                {
                    best_score = sc;
                    best_node = cur;
                    best_st = st;
                }

                if (policy == 0 && noise == 0) break;
            }

            cur = h_next_[cur];
        }

        int nd = best_node;
        int st = best_st;

        off[i] = st;

        long long top = (long long)st + sz;
        if (top &gt; peak) peak = top;

        int lo = h_lo_[nd];
        int hi = h_hi_[nd];

        if (st &gt; lo && (long long)st + sz &lt; hi)
        {
            h_hi_[nd] = st;
            int nn = hole_alloc_node();
            h_lo_[nn] = st + sz;
            h_hi_[nn] = hi;
            h_prev_[nn] = nd;
            h_next_[nn] = h_next_[nd];
            h_prev_[h_next_[nd]] = nn;
            h_next_[nd] = nn;
        }
        else if (st &gt; lo)
        {
            h_hi_[nd] = st;
        }
        else if ((long long)st + sz &lt; hi)
        {
            h_lo_[nd] = st + sz;
        }
        else
        {
            h_prev_[h_next_[nd]] = h_prev_[nd];
            h_next_[h_prev_[nd]] = h_next_[nd];
            hole_release_node(nd);
        }
    }

    return peak;
}

static long long reinsert_band(int n, const Tensor *t, int *off, long long thresh, int shake)
{
    int rm = 0;

    for (int i = 0; i &lt; n; ++i)
    {
        if ((long long)off[i] + t[i].size &gt; thresh || (shake &gt; 0 && rnd_next() % shake == 0))
        {
            rm_list_[rm++] = i;
            placed_[i] = 0;
        }
        else
        {
            placed_[i] = 1;
        }
    }

    int kv = rnd_next() % 3;
    int use_bf = rnd_next() % 2;

    for (int x = 0; x &lt; rm; ++x)
    {
        int i = rm_list_[x];
        if (kv == 0)
            key_[i] = ((long long)(-t[i].size) &lt;&lt; 20) + (rnd_next() % 1024);
        else if (kv == 1)
            key_[i] = ((long long)(-t[i].align) &lt;&lt; 40) + ((long long)(-t[i].size) &lt;&lt; 20) + (rnd_next() % 1024);
        else
            key_[i] = rnd_next();
    }
    sort_idx(rm_list_, 0, rm - 1);

    for (int x = 0; x &lt; rm; ++x)
    {
        int i = rm_list_[x];
        int cand;
        if (use_bf)
            cand = best_fit(n, t, off, i, thresh);
        else
            cand = lowest_fit_h(n, t, off, i, 1, thresh);
        off[i] = cand;
        placed_[i] = 1;
    }

    long long peak = 0;
    for (int i = 0; i &lt; n; ++i)
    {
        long long top = (long long)off[i] + t[i].size;
        if (top &gt; peak) peak = top;
    }

    return peak;
}

static long long evict_and_reinsert(int n, const Tensor *t, int *off, int target, int st)
{
    int rm = 0;

    for (int i = 0; i &lt; n; ++i) placed_[i] = 1;
    placed_[target] = 0;

    int te = st + t[target].size;

    if (adj_ok_)
    {
        int p_end = head_[target] + deg_[target];
        for (int p = head_[target]; p &lt; p_end; ++p)
        {
            int j = adj_[p];
            if (off[j] &lt; te && st &lt; off[j] + t[j].size)
            {
                rm_list_[rm++] = j;
                placed_[j] = 0;
            }
        }
    }
    else
    {
        for (int j = 0; j &lt; n; ++j)
        {
            if (j == target) continue;
            if (t[target].start &lt; t[j].end && t[j].start &lt; t[target].end)
            {
                if (off[j] &lt; te && st &lt; off[j] + t[j].size)
                {
                    rm_list_[rm++] = j;
                    placed_[j] = 0;
                }
            }
        }
    }

    off[target] = st;
    placed_[target] = 1;

    for (int x = 0; x &lt; rm; ++x)
    {
        int i = rm_list_[x];
        key_[i] = ((long long)(-t[i].size) &lt;&lt; 20) + (rnd_next() % 1024);
    }
    sort_idx(rm_list_, 0, rm - 1);

    for (int x = 0; x &lt; rm; ++x)
    {
        int i = rm_list_[x];
        int cand = lowest_fit_h(n, t, off, i, 1, (st + t[target].size) * 2);
        off[i] = cand;
        placed_[i] = 1;
    }

    long long peak = 0;
    for (int i = 0; i &lt; n; ++i)
    {
        long long top = (long long)off[i] + t[i].size;
        if (top &gt; peak) peak = top;
    }

    return peak;
}

static void try_seed(int n, const Tensor *t, long long *best_peak)
{
    sort_idx(ord_, 0, n - 1);

    long long peak = place_order(n, t, off_cur_, 0, 0x3fffffffffffffffLL);

    if (peak &lt; *best_peak)
    {
        *best_peak = peak;
        for (int i = 0; i &lt; n; ++i) off_best_[i] = off_cur_[i];
