}

static long long time_band_reinsert(int n, const Tensor *t, int *off, int w0, int w1, long long thresh)
{
    int rm = 0;

    for (int i = 0; i &lt; n; ++i)
    {
        placed_[i] = 1;

        if (t[i].start &lt; w1 && w0 &lt; t[i].end && (long long)off[i] + t[i].size &gt; thresh)
        {
            rm_list_[rm++] = i;
            placed_[i] = 0;
        }
    }

    for (int x = 0; x &lt; rm; ++x)
    {
        int i = rm_list_[x];
        key_[i] = ((long long)(-t[i].size) &lt;&lt; 20) + (rnd_next() % 1024);
    }
    sort_idx(rm_list_, 0, rm - 1);

    for (int x = 0; x &lt; rm; ++x)
    {
        int i = rm_list_[x];
        int cand = lowest_fit_h(n, t, off, i, 1, thresh);
        off[i] = cand;
        placed_[i] = 1;
    }

    long long peak = 0;
    for (int i = 0; i &lt; n; ++i)
    {
        long long top = (long long)off[i] + t[i].size;
        if (top &gt; peak) peak = top;
