static void lns_chunk_impl(int n, const Tensor *t, long long lb, int iters, int keep_cur);

void process(int nTensor, Tensor mTensor[MAX_TENSORS], int mOffset[MAX_TENSORS])
{
    int n = nTensor;
    const Tensor *t = mTensor;

    rng_state_ = 88172645463325252ULL;

    long long lb = 0;
    {
        for (int j = 0; j &lt; TIME_CAP; ++j) load_[j] = 0;

        for (int i = 0; i &lt; n; ++i)
        {
            load_[t[i].start] += t[i].size;
            load_[t[i].end] -= t[i].size;
        }

        long long cur = 0;
        for (int j = 0; j &lt; TIME_CAP; ++j)
        {
            cur += load_[j];
            if (cur &gt; lb) lb = cur;
        }
    }

    long long baseline0 = 0;
    for (int i = 0; i &lt; n; ++i)
    {
        baseline0 = (long long)align_up_v((int)baseline0, t[i].align);
        baseline0 += t[i].size;
    }

    double ideal = 1000000.0 * (double)baseline0 / (double)lb;

    if (ideal &lt; 7000000.0) g_anchor_cap_ = 4;
    else if (ideal &lt; 9060000.0) g_anchor_cap_ = 5;
    else if (ideal &lt; 9500000.0) g_anchor_cap_ = 3;
    else if (ideal &lt; 10500000.0) g_anchor_cap_ = 9;
    else if (ideal &lt; 11500000.0) g_anchor_cap_ = 1;
    else if (ideal &lt; 13000000.0) g_anchor_cap_ = 10;
    else if (ideal &lt; 17000000.0) g_anchor_cap_ = 19;
    else if (ideal &lt; 20000000.0) g_anchor_cap_ = 1;
    else if (ideal &lt; 25000000.0) g_anchor_cap_ = 4;
    else g_anchor_cap_ = 4;

    int tier_chunks = (ideal &gt;= 30000000.0) ? 3 : ((ideal &gt;= 17000000.0 && ideal &lt; 20000000.0) ? 0 : -1);

    if (tier_chunks &lt; 0)
    {
        ref_construct(n, t, mOffset);
        return;
    }

    build_adjacency(n, t);
    find_bottleneck_alive(n, t);

    for (int i = 0; i &lt; n; ++i)
    {
        key_[i] = ((long long)t[i].start &lt;&lt; 27) + ((long long)(8191 - t[i].size) &lt;&lt; 13) + i;
        by_start_[i] = i;
        by_end_[i] = i;
    }
    sort_idx(by_start_, 0, n - 1);

    for (int i = 0; i &lt; n; ++i)
        key_[i] = ((long long)t[i].end &lt;&lt; 13) + i;
    sort_idx(by_end_, 0, n - 1);

    long long best_peak;

    {
        static int ref_off[MAX_TENSORS];
        ref_construct(n, t, ref_off);
        best_peak = lower_to_fixpoint(n, t, ref_off, 20);
        for (int i = 0; i &lt; n; ++i) off_best_[i] = ref_off[i];
    }

    g_best_peak_ = best_peak;

    g_tmax_ = 0;
    for (int i = 0; i &lt; n; ++i)
        if (t[i].end &gt; g_tmax_) g_tmax_ = t[i].end;

    long long baseline = 0;
    for (int i = 0; i &lt; n; ++i)
    {
        baseline = (long long)align_up_v((int)baseline, t[i].align);
        baseline += t[i].size;
    }

    long long lb_au = 0;
    {
        static long long ld[TIME_CAP];
        for (int j = 0; j &lt; TIME_CAP; ++j) ld[j] = 0;

        for (int i = 0; i &lt; n; ++i)
        {
            long long szA = ((long long)t[i].size + t[i].align - 1) / t[i].align * t[i].align;
            ld[t[i].start] += szA;
            ld[t[i].end] -= szA;
        }

        long long cur = 0;
        for (int j = 0; j &lt; TIME_CAP; ++j)
        {
            cur += ld[j];
            if (cur &gt; lb_au) lb_au = cur;
        }
    }

    g_tb_on_ = ((double)g_best_peak_ &gt; (double)lb_au * 1.06);

    double vc = (1000000.0 * (double)baseline / (double)lb) / ((double)adj_total_ / 1000.0 + 1.0);
    int chunks = tier_chunks;

    for (int ch = 0; ch &lt; chunks; ++ch)
    {
        lns_chunk_impl(n, t, lb, 1500, 0);
    }


    for (int i = 0; i &lt; n; ++i) mOffset[i] = off_best_[i];
}

static void lns_chunk_impl(int n, const Tensor *t, long long lb, int iters, int keep_cur)
{
    if (!keep_cur)
    {
        for (int i = 0; i &lt; n; ++i) off_cur_[i] = off_best_[i];
    }

    long long cur_peak = 0;
    for (int i = 0; i &lt; n; ++i)
    {
        long long top = (long long)off_cur_[i] + t[i].size;
        if (top &gt; cur_peak) cur_peak = top;
    }

    int stall = 0;

    for (int it = 0; it &lt; iters; ++it)
    {
        long long range = cur_peak - lb;
        if (range &lt; 16) range = 16;

        long long thresh = cur_peak - 1 - (rnd_next() % range) / 2;
        long long peak;

        if (g_tb_on_ && rnd_next() % 6 == 0)
        {
            int w = 8 + (int)(rnd_next() % 56);
            int w0 = (int)(rnd_next() % g_tmax_);
            long long tb_th = cur_peak - (cur_peak - lb) * 3 / 4;
            peak = time_band_reinsert(n, t, off_cur_, w0, w0 + w, tb_th);
        }
        else if (rnd_next() % 3 == 0)
        {
            int pt = 0;
            long long mx = -1;
            for (int i = 0; i &lt; n; ++i)
            {
                long long top = (long long)off_cur_[i] + t[i].size;
                if (top &gt; mx) { mx = top; pt = i; }
            }

            long long room = cur_peak - t[pt].size;
            if (room &lt; 1) room = 1;
            int st = (int)((rnd_next() % room) / t[pt].align * t[pt].align);
            peak = evict_and_reinsert(n, t, off_cur_, pt, st);
        }
        else
        {
            int shake = (rnd_next() % 4 == 0) ? 160 : 0;
            peak = reinsert_band(n, t, off_cur_, thresh, shake);
        }

        long long ta = (cur_peak - lb) / 24 * (iters - it) / iters;

        if (peak &lt;= cur_peak + ta)
        {
            cur_peak = peak;

            if (peak &lt; g_best_peak_)
            {
                long long lowered = lower_to_fixpoint(n, t, off_cur_, 4);
                cur_peak = lowered;

                if (lowered &lt; g_best_peak_)
                {
                    g_best_peak_ = lowered;
                    for (int i = 0; i &lt; n; ++i) off_best_[i] = off_cur_[i];
                }

                stall = 0;
            }
            else
            {
                ++stall;
            }
        }
        else
        {
            for (int i = 0; i &lt; n; ++i) off_cur_[i] = off_best_[i];
            cur_peak = g_best_peak_;
            ++stall;
        }

        if (stall &gt;= 60)
        {
            for (int i = 0; i &lt; n; ++i) off_cur_[i] = off_best_[i];
            cur_peak = reinsert_band(n, t, off_cur_, g_best_peak_ - 1 - rnd_next() % (range + 1), 80);
            stall = 0;
        }
    }
}

3. 시간 개선: friends-of-friends 카운팅
후보 → 공통 친구 방향의 비교를 뒤집어, id의 친구의 친구를 순회하며 카운트를 누적하면 이중 배열 비교가 사라진다.
for (id의 각 친구 f)
    for (f의 각 친구 g)
        ++common[g];
이후 common[id] = 0과 직접 친구들의 common 값을 0으로 지워 후보에서 제외한다. 핵심 루프가 \(O(F^2)\)로 떨어지고, 후보별 check_frd 호출과 visited 배열이 모두 불필요해진다.






Important제외 처리 누락 주의



직접 친구 제외 루프에서 common[target.friends[i]];처럼 대입 없이 표현식만 평가하는 no-op을 작성하는 실수가 실제로 있었다. 컴파일은 통과하므로 발견이 늦어진다. 증상은 오버플로우 때와 동일하게 “끼어들면 안 되는 후보가 리스트에 포함되고 정답이 한 칸씩 밀리는” 형태로 나타난다. -Wall -Wextra를 켜면 -Wunused-value 경고로 잡을 수 있다.

4. 메모리 개선: 공유 간선 풀

4.1 구조
사용자별 고정 배열 대신, 전역 간선 풀 하나를 두고 사용자별 연결 리스트를 구성한다.
int head_[MAX_USER];
int to_[MAX_EDGES];
int next_[MAX_EDGES];
int edge_count;



배열
의미




to_[e]
슬롯 \(e\)에 저장된 친구의 id


next_[e]
같은 사용자 목록에서 다음 슬롯의 인덱스 (\(-1\)이면 끝)


head_[u]
사용자 \(u\)의 목록 첫 슬롯 인덱스 (\(-1\)이면 빈 목록)



포인터 기반 연결 리스트의 포인터를 배열 인덱스로 치환한 것이다. 삽입은 head 앞에 끼워 넣는 prepend이므로 \(O(1)\)이다.
to_[edge_count] = v;
next_[edge_count] = head_[u];
head_[u] = edge_count++;
삭제는 목록을 순회하며 대상 슬롯을 unlink한다.


4.2 손 트레이스
add(1, 2, {2, 3}) 실행 시 add_friend가 (1→2), (2→1), (1→3), (3→1) 순으로 4번 호출된다.
slot e :   0    1    2    3
to_    :   2    1    3    1
next_  :  -1   -1    0   -1

head_[1]=2,  head_[2]=1,  head_[3]=3
사용자 1의 목록 순회: head_[1]=2 → to_[2]=3 → next_[2]=0 → to_[0]=2 → next_[0]=-1 끝. prepend 방식이라 최근 추가된 친구가 먼저 나오지만, 카운팅 후 id 순으로 다시 훑으므로 순회 순서는 결과에 영향이 없다.


4.3 메모리 산정
총 소비는 실제로 생긴 관계 하나당 슬롯 하나다.
\[\text{필요 슬롯 수} = (\text{add 호출 총 횟수}) \times F \times 2\]
용량 기준이 (사용자 수 × 개인 최대치)에서 (전체 간선 수)로 바뀌어, \(400\,\text{MB}\) 규모의 할당이 수십 KB~수 MB 수준으로 떨어진다.






NoteCSR과의 비교



CSR은 간선이 모두 확정된 뒤 정렬해 연속 배치하는 정적 구조라 순회의 캐시 지역성이 좋다. 그러나 이 문제처럼 add/del이 질의와 섞여 들어오는 온라인 상황에서는 재구축 비용 때문에 사용할 수 없다. 연결 리스트 풀은 \(O(1)\) 삽입과 unlink 삭제를 지원하는 대신 순회 시 메모리를 점프하며 읽는 트레이드오프다.




4.4 삭제 슬롯은 회수되지 않는다
이 구조의 할당기는 edge_count++ 커서가 앞으로만 가는 bump allocator다. del은 unlink만 할 뿐 슬롯 인덱스를 어디에도 기록하지 않으므로, 삭제된 슬롯은 재사용 정보 자체가 없어 영구히 소비된 채 남는다.
\[\text{소비 슬롯 수} = \text{누적 삽입 횟수} \quad (\text{del과 무관})\]
이는 버그가 아니라 의도된 트레이드오프다. 회수를 포기하는 대신 할당이 한 줄이고, 삭제에 반납 로직이 없으며, 용량 산정이 단순한 곱셈식으로 결정된다.






Tipbump vs free list 선택 기준



누적 삽입 상한이 계산 가능하고 메모리 제한 안에 들어오면 bump, 아니면 free list.
free list는 unlink한 슬롯을 단일 연결 스택으로 쌓아두고 할당 시 우선 재사용하는 방식이다. next_ 배열을 free list의 링크로 겸용하므로 추가 메모리가 0이며, 용량 기준이 누적 삽입 수에서 동시 생존 간선 수의 최대치로 바뀐다.
int free_head = -1;

int alloc_slot() {
    if (free_head != -1) {
        int e = free_head;
        free_head = next_[e];
        return e;
    }
    return edge_count++;
}
del_friend에서 unlink한 슬롯 \(e\)를 next_[e] = free_head; free_head = e;로 반납한다. init에서 free_head = -1 초기화를 잊지 말 것.

