int n_users;
struct User {
    int mId;

    void init(int id) {
        mId = id;
        head_[id] = -1;
    }

    void add_friend(int id) {
        to_[edge_count] = id;
        next_[edge_count] = head_[mId];
        head_[mId] = edge_count;
        ++edge_count;
    }

    void del_friend(int id) {
        int prev = -1;
        for(int e = head_[mId]; e != -1; e = next_[e]) {
            if(to_[e] == id) {
                if(prev == -1) head_[mId] = next_[e];
                else next_[prev] = next_[e];
                return;
            }
            prev = e;
        }
    }
} user[MAX_USER];

void init(int N)
{
    edge_count = 0;
    n_users = N;
    for(int i = 1; i &lt;= n_users; ++i) {
        user[i].init(i);
    }
}

void add(int id, int F, int ids[MAXF])
{
    for(int i = 0; i &lt; F; ++i) {
        user[id].add_friend(ids[i]);
        user[ids[i]].add_friend(id);
    }
}

void del(int id1, int id2)
{
    user[id1].del_friend(id2);
    user[id2].del_friend(id1);
}

int common[MAX_USER];
int recommend(int id, int list[MAXL])
{
    for(int i = 1; i &lt;= n_users; ++i) {
        common[i] = 0;
    }

    for(int e = head_[id]; e != -1; e = next_[e]) {
        int f = to_[e];
        for(int je = head_[f]; je != -1; je = next_[je]) {
            ++common[to_[je]];
        }
    }

    common[id] = 0;
    for(int e = head_[id]; e != -1; e = next_[e]) {
        common[to_[e]] = 0;
    }

    int cnt = 0;
    int max_frds[MAXL] = {0, };

    for(int i = 1; i &lt;= n_users; ++i) {
        if(common[i] == 0) continue;

        int max_c = common[i];

        int tar = 0;
        for(; tar &lt; cnt; ++tar) {
            if(max_frds[tar] &lt; max_c) break;
        }
        for(int tt = MAXL - 1; tt &gt; tar; --tt) {
            max_frds[tt] = max_frds[tt - 1];
            list[tt] = list[tt - 1];
        }
        if(tar != MAXL) {
            max_frds[tar] = max_c;
            list[tar] = i;
        }
        if(cnt != MAXL) ++cnt;
    }

    return cnt;
}

