#include &lt;stdio.h&gt;

using eGroup = enum {
    MAX_GRP = 0,
    CAP,
    RESIDUAL,
    MAX_VAL,
};

template &lt;typename T&gt;
auto _MIN(T a, T b)
{
    return (a &lt; b) ? a : b;
}

template &lt;typename T&gt;
auto _MAX(T a, T b)
{
    return (a &gt; b) ? a : b;
}

