    void append(Node* node) {
        node-&gt;prev = tail.prev;
        node-&gt;next = &tail;

        tail.prev-&gt;next = node;
        tail.prev = node;
    }

    void splice(List* target, int t_score) {
        if(this == target) return;
        if(is_empty()) return;

        Node* first = head.next;
        Node* last = tail.prev;

        Node* t_last = target-&gt;tail.prev;

        t_last-&gt;next = first;
        first-&gt;prev = t_last;

        last-&gt;next = &target-&gt;tail;
        target-&gt;tail.prev = last;

        init();
    }

    int get_best_sd() {
        int max_s_id = -1;
        for(auto nd = head.next; nd != &tail; nd = nd-&gt;next) {
            if(max_s_id &lt; nd-&gt;s_id) {
                max_s_id = nd-&gt;s_id;
            }
        }
        return max_s_id;
    }
} m_list[MAX_TEAM][MAX_SCORE];

void mdelete(Node* node) {
    node-&gt;prev-&gt;next = node-&gt;next;
    node-&gt;next-&gt;prev = node-&gt;prev;
    node-&gt;prev = node-&gt;next = nullptr;
}

void init()
{
    for(int i = 0; i &lt; MAX_TEAM; ++i) {
        for(int j = 0; j &lt; MAX_SCORE; ++j) {
            m_list[i][j].init();
        }
    }
}

void hire(int mID, int mTeam, int mScore)
{
    --mTeam;
    --mScore;

    auto& target = node[mID];
    target.init(mID, mTeam);
    m_list[mTeam][mScore].append(&target);
}

void fire(int mID)
{
    auto& target = node[mID];
    mdelete(&target);
}

void updateSoldier(int mID, int mScore)
{
    --mScore;

    auto& target = node[mID];
    mdelete(&target);
    m_list[target.t_id][mScore].append(&target);
}

void updateTeam(int mTeam, int mChangeScore)
{
    --mTeam;

    if(mChangeScore &lt; 0) {
        for(int sc = 0; sc &lt; MAX_SCORE; ++sc) {
            int tsc = sc + mChangeScore;
            if(tsc &lt; 0) tsc = 0;
            if(tsc &gt;= MAX_SCORE) tsc = MAX_SCORE - 1;

            m_list[mTeam][sc].splice(&m_list[mTeam][tsc], tsc);
        }
    } else {
        for(int sc = MAX_SCORE - 1; sc &gt;= 0; --sc) {
            int tsc = sc + mChangeScore;
            if(tsc &lt; 0) tsc = 0;
            if(tsc &gt;= MAX_SCORE) tsc = MAX_SCORE - 1;

            m_list[mTeam][sc].splice(&m_list[mTeam][tsc], tsc);
        }
    }
}

int bestSoldier(int mTeam)
{
    for(int sc = MAX_SCORE - 1; sc &gt;= 0; --sc) {
        auto ret = m_list[mTeam - 1][sc].get_best_sd();
        if(ret != -1) return ret;
    }

    return -1;
}

